package com.bank.docker;

// One read-only layer = the filesystem diff from one Dockerfile instruction.
public final class ImageLayer {
    private final String instruction; // e.g. "COPY app.jar /app.jar"
    private final String content;     // what this layer adds

    public ImageLayer(String instruction, String content) {
        this.instruction = instruction;
        this.content = content;
    }
    public String getInstruction() { return instruction; }
    public String getContent()     { return content; }
}
