package com.bank.docker;

import java.util.List;

// Immutable, read-only template: ordered layers + metadata (entrypoint).
public final class Image {
    private final String tag;
    private final List<ImageLayer> layers; // base -> deps -> app -> metadata
    private final String entrypoint;

    public Image(String tag, List<ImageLayer> layers, String entrypoint) {
        this.tag = tag;
        this.layers = List.copyOf(layers); // defensive copy = immutable
        this.entrypoint = entrypoint;
    }
    public String getTag()            { return tag; }
    public List<ImageLayer> getLayers(){ return layers; }
    public String getEntrypoint()     { return entrypoint; }

    // Running the image creates a new container instance.
    public Container run(String containerName) {
        return new Container(containerName, this);
    }
}
