package com.bank.docker;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// A running instance of an image, with its OWN thin writable layer.
public class Container {
    private static final Logger log = Logger.getLogger(Container.class.getName());
    private final String name;
    private final Image image;                 // shared read-only layers
    private final List<String> writableLayer = new ArrayList<>(); // per-container
    private boolean running;

    public Container(String name, Image image) {
        this.name = name;
        this.image = image;
    }

    public void start() {
        running = true;
        log.info(() -> "Container '" + name + "' started from image " + image.getTag()
                + " -> " + image.getEntrypoint());
    }

    // Writes go ONLY to this container's writable layer (isolated).
    public void write(String data) {
        writableLayer.add(data);
        log.info(() -> "Container '" + name + "' wrote to its writable layer: " + data);
    }

    public List<String> getWritableLayer() { return List.copyOf(writableLayer); }

    // Removing the container discards its writable layer; image is untouched.
    public void remove() {
        running = false;
        log.warning(() -> "Container '" + name + "' removed -> writable layer ("
                + writableLayer.size() + " items) discarded. Image unchanged.");
        writableLayer.clear();
    }

    public boolean isRunning() { return running; }
}
