package com.bank.docker;

import java.util.List;
import java.util.logging.*;

public class DockerConceptDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new DockerLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(DockerConceptDemo.class.getName());

        // Build ONE immutable image from ordered layers.
        Image image = new Image("transfer-service:1.2.0", List.of(
                new ImageLayer("FROM eclipse-temurin:21-jre", "minimal Linux + JRE 21"),
                new ImageLayer("COPY libs/ /app/libs/",       "runtime dependencies"),
                new ImageLayer("COPY app.jar /app.jar",       "transfer-service application"),
                new ImageLayer("ENV PORT=8080",               "metadata: port")),
                "java -jar /app.jar");

        log.info("=== Image layers (read-only, shared) ===");
        image.getLayers().forEach(l ->
                log.info("  layer: " + l.getInstruction() + "  (" + l.getContent() + ")"));

        log.info("=== Run TWO containers from the SAME image ===");
        Container c1 = image.run("transfer-c1");
        Container c2 = image.run("transfer-c2");
        c1.start();
        c2.start();

        // Each container's writable layer is isolated.
        c1.write("tmp-file: request-log-c1.txt");
        c2.write("tmp-file: request-log-c2.txt");

        log.info("c1 writable layer: " + c1.getWritableLayer());
        log.info("c2 writable layer: " + c2.getWritableLayer());

        log.info("=== Remove c1: its writable layer is gone, image intact ===");
        c1.remove();
        Container c3 = image.run("transfer-c3"); // image still spawns new instances
        c3.start();
    }
}

// ─── Would be in DockerLogFormatter.java in a real project ───
class DockerLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
