```dockerfile
# ─── File: Dockerfile ───
# base image layer: minimal Linux + Java 21 runtime
FROM eclipse-temurin:21-jre
WORKDIR /app
# dependency layer FIRST (changes rarely) -> good caching
COPY libs/ /app/libs/
# application layer LAST (changes often)
COPY target/transfer-service.jar /app/app.jar
ENV PORT=8080
EXPOSE 8080
# metadata: how to start the process
ENTRYPOINT ["java","-jar","/app/app.jar"]
